    return KeyCap(action: .shift, display: display, width: .fill, style: .function)
}

private func backspace_cap() -> KeyCap {
    return KeyCap(action: .backspace, display: "⌫", width: .fill, style: .function)
}

private func bottom_row(plane_key: KeyCap) -> [KeyCap] {
    var row: [KeyCap] = [plane_key]
    // The globe (next-keyboard) key occupies the system's emoji slot; it is
    // only drawn when iOS does not supply its own input-mode switcher. Lex
    // is always Telex, so switching keyboards is how the user types plain
    // Latin / other languages.
    if self.shows_globe {
        row.append(KeyCap(action: .nextKeyboard, display: "🌐", width: .ratio(1.4), style: .function))
    }
    row.append(KeyCap(action: .space, display: "space", width: .fill, style: .letter))
    row.append(KeyCap(action: .character("."), display: ".", width: .unit, style: .letter))
    row.append(KeyCap(action: .enter, display: self.return_title, width: .ratio(1.4), style: .function))
    return row
}

