private func make_button(_ cap: KeyCap) -> KeyButton {
    let button = KeyButton(type: .system)
    button.cap = cap
    button.isMultipleTouchEnabled = true
    button.isExclusiveTouch = false
    button.setTitle(cap.display, for: .normal)
    button.titleLabel?.font = .systemFont(ofSize: cap.style == .letter ? 25 : 18)
    button.titleLabel?.adjustsFontSizeToFitWidth = true
    button.titleLabel?.minimumScaleFactor = 0.5
    button.layer.cornerRadius = 8
    button.layer.cornerCurve = .continuous
    self.apply_colors(to: button)
    return button
}

